import {CITY,LOOKS,ROOFS,GATES,NAV} from './world.mjs';
import {createSession,startSession,stepSession,actionHint} from './physics.mjs';
import {normalizeSave,buyLook,settle} from './progress.mjs';
import {ParkourScene} from './scene.mjs';
import {ParkourInput} from './input.mjs';
import {CityAudio} from './audio.mjs';
import {prepareRunner} from './human-runner.mjs';
import {loadPhotoMaterials} from './materials.mjs';
import {bearing,distance,angleDelta,clamp} from './math.mjs';

const canvas=document.querySelector('#world'),ui=document.querySelector('#ui'),toastNode=document.querySelector('#toast'),params=new URLSearchParams(location.search),key='rooftop-flow-v1'+(params.has('qa')?'-qa':'');
function load(){try{return normalizeSave(JSON.parse(localStorage.getItem(key)));}catch{return normalizeSave(null);}}
let save=load(),world=createSession({ghost:save.ghost}),view='home',mapReturn='home',helpReturn='home',previewLook=save.look,result=null,scene,thumbs={},last=performance.now(),elapsed=0,accumulator=0,hudClock=0,toastUntil=0,lastEvent=0;
const orbit={yaw:0,pitch:.28,showGhost:save.showGhost},audio=new CityAudio();audio.enabled=save.sound;
let perfFrames=0,perfSeconds=0;const perfNode=params.has('qa')?document.body.appendChild(Object.assign(document.createElement('div'),{id:'qa-performance'})):null;if(perfNode)perfNode.style.cssText='position:absolute;top:64px;left:50%;transform:translateX(-50%);padding:4px 8px;background:#152c38d9;color:#d8e7ca;font:10px monospace;pointer-events:none;z-index:20;white-space:nowrap';
try{document.querySelector('#loading b').textContent='正在准备城市与人物';const [,pbr]=await Promise.all([prepareRunner(),loadPhotoMaterials()]);scene=new ParkourScene(canvas,world.map,{pbr});scene.applyLook(save.look);thumbs=scene.thumbnails();document.querySelector('#loading').remove();}catch(e){document.querySelector('#loading').innerHTML='<b>城市还没打开</b><span>请使用支持WebGL2的Chrome或Edge后刷新，并检查本地素材是否齐全</span>';console.error(e);throw e;}
const input=new ParkourInput(canvas,orbit,()=>view==='race'&&world.mode==='running',()=>{if(view==='race')pause();else if(view==='pause')resume();else if(view==='help'){view=helpReturn;render();}});
const time=t=>`${Math.floor(t/60).toString().padStart(2,'0')}:${(t%60).toFixed(1).padStart(4,'0')}`;
const wallet=()=>`<div class="wallet" aria-label="城市徽币余额"><span>◈</span><b>${save.coins}</b></div>`;
const brand=()=>`<div class="brand"><i>↗</i><span>ROOFTOP<span>FLOW / 城市跑酷</span></span></div>`;
function persist(){try{localStorage.setItem(key,JSON.stringify(save));}catch{try{const light={...save,ghost:[]};localStorage.setItem(key,JSON.stringify(light));toast('记录已保存 · 当前浏览器空间不足，影子暂未保存');}catch{toast('浏览器暂时无法保存进度');}}}
function toast(text){toastNode.textContent=text;toastNode.classList.add('show');toastUntil=elapsed+2.8;}
function start(practice=false){input.reset();world=createSession({practice,ghost:save.ghost});startSession(world,{waitForMove:true});orbit.yaw=0;orbit.pitch=.28;orbit.showGhost=save.showGhost;input.fastRun=false;view='race';result=null;accumulator=0;lastEvent=0;scene.lastEvent=0;scene.lastFoot=-1;scene.snap=true;scene.applyLook(save.look);audio.reset();audio.unlock();render();}
function pause(){if(view!=='race'||world.mode!=='running')return;world.mode='paused';view='pause';input.reset();render();}
function resume(){if(!['pause','map','help'].includes(view))return;world.mode='running';view='race';input.reset();accumulator=0;audio.unlock();render();}
function home(){input.reset();world.mode='ready';view='home';scene.applyLook(save.look);render();}
function openWardrobe(){previewLook=save.look;view='wardrobe';input.reset();scene.applyLook(previewLook);scene.previewYaw=-.22;render();}
function minimap(full=false){return `<svg class="${full?'route-map':'mini-map'}" viewBox="-22 -230 96 260" aria-label="城市屋顶路线图"><path d="M-22 -230H74V30H-22Z" fill="#112a35"/>${ROOFS.map(r=>`<rect x="${r.x-r.w/2}" y="${r.z-r.d/2}" width="${r.w}" height="${r.d}" rx=".7" fill="#657b7c" stroke="#a4b3a7" stroke-width=".4"/>`).join('')}<polyline points="${NAV.map(p=>p.x+','+p.z).join(' ')}" fill="none" stroke="#d7c172" stroke-width=".7" stroke-dasharray="2 1.8"/>${GATES.map((g,i)=>`<circle cx="${g.x}" cy="${g.z}" r="${full?2.0:1.7}" fill="${i<=world.gate?'#b9e895':'#f0d892'}"/>`).join('')}<g id="map-player" transform="translate(${world.player.x},${world.player.z}) rotate(${-world.player.yaw*180/Math.PI})"><path d="M0 -3.6L2.4 2.8 0 1.4 -2.4 2.8Z" fill="#f2f7ed" stroke="#1a3136" stroke-width=".5"/></g></svg>`;}
function homeHTML(){return `<div class="home-scrim"></div><header class="topbar">${brand()}<div class="top-actions">${wallet()}<button class="icon-button" data-action="sound" aria-label="${save.sound?'关闭声音':'开启声音'}">${save.sound?'♫':'♪'}</button><button class="icon-button" data-action="help" aria-label="操作指南">?</button></div></header><section class="hero"><div class="eyebrow"><span class="status-dot"></span> OLD TOWN / CITY PARKOUR</div><h1>ROOFTOP<br><em>FLOW.</em></h1><h2>屋顶疾行</h2><p class="hero-copy">助跑、起跳、翻越。<br>把城市，跑成自己的路线。</p><div class="hero-facts"><span>真实三维跑酷</span><span>多条高空近路</span><span>自己的最佳影子</span></div><div class="home-buttons"><button class="primary" data-action="start">开始跑酷 <span>↗</span></button><button class="secondary" data-action="practice">自由练习 <small>自在探索 · 快速重试</small></button><div class="home-links"><button data-action="wardrobe">◈ 街头衣橱</button><button data-action="map">⌁ 路线总览</button></div></div><div class="personal-best">${save.best?`<span>PERSONAL BEST</span><b>${time(save.best.time)}</b><small>下一趟，和自己的影子一起出发。</small>`:`<span>YOUR FIRST LINE</span><b>老城天际线</b><small>8座主楼顶 · 检查点接续 · 外观随挑战解锁</small>`}</div></section><div class="home-coordinate"><span>THE CITY IS YOUR PLAYGROUND</span><i>01 / 老城天际线</i></div>`;}
function hudHTML(){return `<header class="run-top"><div class="run-time"><span>${world.practice?'FREE ROAM':'TIME TRIAL'}</span><b id="timer">00:00.0</b><small id="penalty">${world.practice?'自由练习 · 不结算徽币':'老城天际线'}</small></div><div class="run-progress"><span id="checkpoint-label">检查点 0 / 8</span><div>${GATES.slice(1).map((_,i)=>`<i id="gate-${i}"></i>`).join('')}</div></div><button class="icon-button pause-icon" data-action="pause" aria-label="暂停跑酷">Ⅱ</button></header><div class="flow-meter"><span>FLOW</span><b id="flow-value">×1.00</b><small id="style-score">0 PTS</small><i><i id="flow-bar"></i></i></div><div class="nav-panel">${minimap()}<button class="route-heading" data-action="look-route" aria-label="看向下一处路线标记"><span id="route-arrow">↑</span><div><b id="next-title">低栏 · 起跳翻越</b><small><span id="next-distance">10m</span> · 点击对准路线</small></div></button></div><div class="action-message" id="action-message"><span id="action-icon">↗</span><span id="action-cue">沿黄色路标前进</span></div><div class="speed-readout"><b id="speed-value">0</b><span>KM/H</span></div><div class="assist-controls"><button data-action="autorun" aria-label="切换连续跑步" id="autorun-button">连续跑 <b>OFF</b></button><button data-action="sprint" aria-label="切换全速奔跑" id="sprint-button">全速 <b>OFF</b></button></div><div class="move-zone"><div class="stick" id="stick" role="group" aria-label="移动摇杆"><span>移动</span><i id="stick-knob"></i><em>W A S D</em></div><div class="camera-nudges"><button data-action="look-left" aria-label="视角向左转">‹</button><button data-action="look-route" aria-label="对准路线">↗</button><button data-action="look-right" aria-label="视角向右转">›</button></div></div><div class="action-buttons"><button class="trick-button" data-action="trick" aria-label="空中转体"><i>⟳</i><span>转体 <small>F</small></span></button><button class="jump-button" data-action="jump" aria-label="跳跃或翻越"><i>↗</i><span id="jump-label">起跳 / 翻越</span><small>SPACE</small></button><button class="slide-button" data-action="slide" aria-label="滑铲或松手"><i>⌁</i><span>滑铲 <small>C</small></span></button></div><div class="desktop-hints"><span><kbd>WASD</kbd> 移动</span><span><kbd>SHIFT</kbd> 加速</span><span><kbd>SPACE</kbd> 跳跃 / 抓边</span><span>拖动视角 · <kbd>Q E</kbd> 转动</span></div><div class="ghost-status" id="ghost-status">${save.best&&save.showGhost?'◌ 个人最佳 '+time(save.best.time):'每一趟，都能找到更好的路线'}</div>`;}
function pauseHTML(){return `<div class="modal-scrim"></div><section class="dialog pause-dialog"><div class="eyebrow">TAKE A BREATH</div><h2>城市，等你一会儿。</h2><p>${time(world.clock)} <span> / </span> 检查点 ${world.gate} / 8</p><button class="primary" data-action="resume">继续跑酷 <span>↗</span></button><div class="dialog-grid"><button class="secondary" data-action="restart">重新出发</button><button class="secondary" data-action="map">查看路线</button></div><div class="setting-row"><span>环境与动作声音</span><button data-action="sound" class="toggle ${save.sound?'on':''}" aria-label="${save.sound?'关闭声音':'开启声音'}">${save.sound?'开启':'关闭'}</button></div><div class="setting-row"><span>${save.ghost.length?'显示自己的最佳影子':'完成挑战后留下自己的影子'}</span><button data-action="ghost" class="toggle ${save.showGhost?'on':''}" ${save.ghost.length?'':'disabled'}>${save.showGhost?'开启':'关闭'}</button></div><button class="text-button" data-action="home">返回天台 · 本局不结算</button></section>`;}
function wardrobeHTML(){const l=LOOKS.find(l=>l.id===previewLook),owned=save.owned.includes(l.id);return `<header class="topbar"><button class="back-button" data-action="home" aria-label="返回天台">‹</button><div class="wardrobe-title"><span>STREET / WARDROBE</span><h2>街头衣橱</h2></div>${wallet()}</header><section class="wardrobe-panel"><div class="wardrobe-caption"><span>01 / ORIGINAL RUNNERS</span><h3>${l.name}</h3><p>${owned?'已经拥有，随时出发。':'用挑战赚到的徽币，换一身新风格。'}</p></div><div class="look-grid">${LOOKS.map(look=>`<button class="look-card ${previewLook===look.id?'selected':''}" data-action="preview-look" data-id="${look.id}" aria-label="试穿${look.name}" aria-pressed="${previewLook===look.id}"><img alt="${look.name}实际三维外观" src="${thumbs[look.id]}"><span>${look.name}</span><small>${save.owned.includes(look.id)?'已拥有':'◈ '+look.price}</small></button>`).join('')}</div><button class="primary buy-button" data-action="buy-look" ${!owned&&save.coins<l.price?'disabled':''}>${owned?(save.look===l.id?'已经穿好啦':'换上这一套'):`解锁并穿上 · ${l.price} ◈`}</button><p class="wardrobe-note">外观不改变速度与跳跃能力</p><button class="text-button" data-action="start">准备好了，出发 ↗</button></section>`;}
function resultHTML(){const r=result,medal=r?.medal,medals={gold:['金牌路线','#edce78'],silver:['银牌路线','#d6e1df'],bronze:['铜牌路线','#d7a885'],finish:['完成挑战','#addba0']};const title=r?.practice?'练习，也是一种前进。':r?.isBest?'这一趟，突破了自己。':'又跑出一条自己的线。';return `<div class="result-shade"></div><section class="result-panel"><div class="eyebrow">${r?.practice?'FREE ROAM COMPLETE':'LINE COMPLETE / OLD TOWN'}</div><div class="medal-label">${r?.practice?'自由探索':medals[medal]?.[0]||'抵达天际线'}</div><h2>${title}</h2><span class="result-time-label">${r?.practice?'探索时间':'完赛时间'}</span><b class="result-time">${time(r?.time||world.clock)}</b><div class="result-stats"><div><small>动作得分</small><b>${world.score}<i> PTS</i></b></div><div><small>翻越 / 攀上</small><b>${world.stats.vaults} / ${world.stats.climbs}</b></div><div><small>沿墙奔跑</small><b>${world.stats.wallruns}<i> 次</i></b></div><div><small>失足重试</small><b>${world.stats.falls}<i> 次</i></b></div></div>${r?.practice?'<p class="result-note">自由练习不结算徽币。随时挑战一次完整路线。</p>':`<div class="reward"><span>◈ +${r?.reward||0}</span><small>城市徽币已到账${r?.isBest&&save.ghost.length?'<br>个人最佳影子已保存':''}</small></div>`}<button class="primary" data-action="start">再跑一趟 <span>↗</span></button><div class="dialog-grid"><button class="secondary" data-action="wardrobe">去换装</button><button class="secondary" data-action="practice">自由练习</button></div><button class="text-button" data-action="home">返回天台</button></section>`;}
function mapHTML(){return `<div class="map-shade"></div><header class="topbar"><button class="back-button" data-action="map-back" aria-label="关闭路线总览">‹</button><div class="map-title"><span>THE HIGH LINE</span><h2>老城天际线</h2></div></header><section class="map-panel">${minimap(true)}<div><div class="eyebrow">FIND YOUR OWN LINE</div><h3>城市，有很多种跑法。</h3><p><i class="legend-line"></i> 黄色路标：连起8座主楼顶</p><p><i class="legend-line mint"></i> 薄荷标记：沿墙奔跑近路</p><p>断口起跳，低栏翻越，高台抓边。<br>每个检查点，都是一次新的出发。</p><div class="medal-times"><span>金牌 <b>01:25</b></span><span>银牌 <b>02:05</b></span><span>铜牌 <b>03:00</b></span></div><button class="primary" data-action="${mapReturn==='home'?'start':'map-back'}">${mapReturn==='home'?'去跑一趟':'返回跑酷'} <span>↗</span></button></div></section>`;}
function helpHTML(){return `<div class="modal-scrim"></div><section class="dialog help-dialog"><div class="eyebrow">GET INTO THE FLOW</div><h2>跑起来，就会懂。</h2><div class="help-grid"><span><kbd>WASD / ↑↓←→</kbd> 移动</span><span><kbd>SHIFT</kbd> 全速奔跑</span><span><kbd>SPACE</kbd> 跳跃 / 翻越</span><span><kbd>C</kbd> 滑铲 / 松手</span><span><kbd>F</kbd> 空中转体</span><span><kbd>R</kbd> 连续跑步</span></div><p>鼠标或右手拖动调整镜头；左侧摇杆移动。<br>点击路线箭头，可以把镜头对准下一处路标。</p><p>贴近低栏起跳会翻越；够到高台会抓边，继续向前便能攀上。沿墙奔跑时，再跳一次就能蹬出。</p><p class="help-soft">失足后从最近检查点继续，计时挑战加2秒。<br>外观只改变风格；影子来自你自己的最佳纪录。</p><button class="primary" data-action="help-back">明白了，继续 ↗</button></section>`;}
function render(){ui.className='view-'+view;ui.innerHTML=view==='home'?homeHTML():view==='race'?hudHTML():view==='pause'?hudHTML()+pauseHTML():view==='wardrobe'?wardrobeHTML():view==='result'?resultHTML():view==='map'?mapHTML():helpHTML();if(view==='race')input.bindHUD(ui);hudClock=.15;updateHUD();}
function updateHUD(){if(!['race','pause'].includes(view))return;const p=world.player,n=NAV[Math.min(world.nav,NAV.length-1)],hint=actionHint(world,{x:-Math.sin(orbit.yaw),z:-Math.cos(orbit.yaw)}),set=(id,text)=>{const e=ui.querySelector('#'+id);if(e&&e.textContent!==String(text))e.textContent=text;};set('timer',time(world.clock));set('penalty',world.waitingForMove?'移动后开始计时':world.practice?'自由练习 · 随时探索':world.penalty?`已计入 ${world.penalty.toFixed(0)}秒重试时间`:'老城天际线');set('checkpoint-label',`检查点 ${world.gate} / 8`);set('speed-value',Math.round(p.speed*3.6));set('style-score',world.score+' PTS');set('flow-value','×'+(1+.15*Math.max(0,world.combo-1)).toFixed(2));const bar=ui.querySelector('#flow-bar');if(bar)bar.style.transform=`scaleX(${world.combo?clamp((world.comboUntil-world.elapsed)/4.2,0,1):0})`;for(let i=0;i<8;i++)ui.querySelector('#gate-'+i)?.classList.toggle('passed',i<world.gate);
 set('next-title',n.name);set('next-distance',Math.round(distance(p,n))+'m');const arrow=ui.querySelector('#route-arrow');if(arrow)arrow.style.transform=`rotate(${-angleDelta(orbit.yaw,bearing(p,n))*180/Math.PI}deg)`;
 set('action-cue',hint.text);const cue=ui.querySelector('#action-message');if(cue)cue.className='action-message '+hint.type;set('action-icon',hint.type==='gap'?'↗':hint.type==='slide'?'⌁':hint.type==='climb'?'↑':hint.type==='wallrun'?'⤴':'↗');set('jump-label',p.hang?'攀上':p.mode==='wallrun'?'蹬墙跃出':hint.type==='vault'?'翻越低栏':'起跳 / 翻越');
 const trick=ui.querySelector('.trick-button');if(trick)trick.classList.toggle('available',!p.grounded&&!p.hang&&!p.kinematic);const auto=ui.querySelector('#autorun-button');if(auto){auto.classList.toggle('on',input.autoRun);auto.querySelector('b').textContent=input.autoRun?'ON':'OFF';}const fast=ui.querySelector('#sprint-button');if(fast){fast.classList.toggle('on',input.fastRun);fast.querySelector('b').textContent=input.fastRun?'ON':'OFF';}ui.querySelector('#map-player')?.setAttribute('transform',`translate(${p.x},${p.z}) rotate(${-p.yaw*180/Math.PI})`);
}
ui.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const a=button.dataset.action;
 if(a==='start')start(false);else if(a==='practice')start(true);else if(a==='pause')pause();else if(a==='resume')resume();else if(a==='restart')start(world.practice);else if(a==='home')home();else if(a==='wardrobe')openWardrobe();else if(a==='preview-look'){previewLook=button.dataset.id;scene.applyLook(previewLook);render();}else if(a==='buy-look'){if(buyLook(save,previewLook)){persist();scene.applyLook(save.look);toast('换好了 · 跑出自己的风格');render();}}
 else if(a==='sound'){save.sound=!save.sound;audio.setEnabled(save.sound);persist();render();}else if(a==='ghost'){save.showGhost=!save.showGhost;orbit.showGhost=save.showGhost;persist();render();}
 else if(a==='autorun'){input.autoRun=!input.autoRun;if(input.autoRun)audio.unlock();updateHUD();}else if(a==='sprint'){input.fastRun=!input.fastRun;updateHUD();}
 else if(a==='look-left'){orbit.yaw+=Math.PI/12;updateHUD();}else if(a==='look-right'){orbit.yaw-=Math.PI/12;updateHUD();}else if(a==='look-route'){orbit.yaw=bearing(world.player,NAV[Math.min(world.nav,NAV.length-1)]);updateHUD();}
 else if(a==='map'){mapReturn=view==='home'?'home':'pause';if(world.mode==='running')world.mode='paused';input.reset();view='map';render();}else if(a==='map-back'){view=mapReturn;scene.snap=true;render();}
 else if(a==='help'){helpReturn=view;if(world.mode==='running')world.mode='paused';input.reset();view='help';render();}else if(a==='help-back'){view=helpReturn;render();}
});
window.addEventListener('resize',()=>{scene.resize();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&view==='race')pause();});
function frame(now){const rawDt=(now-last)/1000,dt=Math.min(.05,rawDt);last=now;elapsed+=dt;if(perfNode){perfFrames++;perfSeconds+=rawDt;if(perfSeconds>=1){perfNode.textContent=`QA · ${Math.round(perfFrames/perfSeconds)} FPS / ${Math.round((scene.renderer.info.render.triangles||0)/1000)}k triangles / ${scene.renderer.info.render.calls} draws / ${(scene.cpuMs||0).toFixed(1)}ms CPU`;perfFrames=perfSeconds=0;}}
 if(view==='race'&&world.mode==='running'){accumulator+=dt;if(accumulator>=1/120){const controls=input.read(dt);let jump=controls.jump,slide=controls.slide,trick=controls.trick;while(accumulator>=1/120&&world.mode==='running'){stepSession(world,{...controls,jump,slide,trick},1/120);jump=slide=trick=false;accumulator-=1/120;}}
  for(const ev of world.events)if(ev.id>lastEvent){lastEvent=ev.id;if(['vault','mantle','wallrun','precision','trickland','checkpoint','respawn'].includes(ev.type))toast((ev.points?'+'+ev.points+' · ':'')+ev.text);}
  if(world.finished){result=world.practice?{practice:true,time:world.clock}:settle(world,save);if(!world.practice)persist();input.reset();toastNode.classList.remove('show');toastUntil=0;view='result';render();}
 }
 audio.update(world);scene.update(world,view,dt,elapsed,orbit);hudClock+=dt;if(hudClock>.09){updateHUD();hudClock=0;}if(toastUntil&&elapsed>toastUntil){toastNode.classList.remove('show');toastUntil=0;}requestAnimationFrame(frame);
}
render();requestAnimationFrame(frame);

export class CityAudio{
 constructor(){this.ctx=null;this.enabled=true;this.active=false;this.foot=-1;this.event=0;}
 unlock(){if(!this.enabled)return;try{this.ctx??=new(window.AudioContext||window.webkitAudioContext)();if(!this.master){this.master=this.ctx.createGain();this.master.gain.value=.7;this.master.connect(this.ctx.destination);const buffer=this.ctx.createBuffer(1,this.ctx.sampleRate*2,this.ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;this.noise=buffer;const source=this.ctx.createBufferSource();source.buffer=buffer;source.loop=true;const filter=this.ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=650;this.wind=this.ctx.createGain();this.wind.gain.value=0;source.connect(filter);filter.connect(this.wind);this.wind.connect(this.master);source.start();}this.ctx.resume().catch(()=>{});}catch{}}
