}
function end(w,status,reason){const h=w.hunt;if(h.status!=='running')return;h.status=status;h.reason=reason;w.finished=true;w.mode='finished';w.player.vx=w.player.vz=w.player.speed=0;event(w,status==='won'?'treasure':'caught',status==='won'?'找到宝藏！':reason==='caught'?'被追逐者抓到了':'生命耗尽');}
export function stepHunt(w,input={},dt=1/120){
 if(w.mode!=='running'||!w.hunt||w.hunt.status!=='running')return;const h=w.hunt;stepSession(w,input,dt);if(w.waitingForMove)return;
 if(w.stats.falls>h.fallCount){let lost=w.stats.falls-h.fallCount;h.fallCount=w.stats.falls;if(h.tool==='feather'&&h.charges>0){lost--;h.charges--;event(w,'tool','轻羽护符生效 · 本次掉落不扣命');}h.lives=Math.max(0,h.lives-lost);h.protectedUntil=w.elapsed+2;if(lost)event(w,'hunt-fall',`掉落 -${lost} 条命 · 剩余 ${h.lives} 条`);if(h.lives===0){end(w,'lost','lives');return;}}
 if(h.tool==='compass'&&w.elapsed>=h.guideAt){h.guidePath=h.nav.path(w.player,h.treasure);h.guideAt=w.elapsed+1.5;}
 if(w.elapsed>=h.headStart)for(const b of h.pursuers)driveBot(w,b,dt);
 h.nearest=Math.min(...h.pursuers.map(b=>Math.hypot(w.player.x-b.state.player.x,w.player.y-b.state.player.y,w.player.z-b.state.player.z)));
 if(w.elapsed>=h.headStart&&w.elapsed>=h.protectedUntil&&h.pursuers.some(b=>w.elapsed>=b.stunnedUntil&&canCapture(w.map,w.player,b.state.player))){end(w,'lost','caught');return;}
 if(w.player.grounded&&!w.player.kinematic&&distance(w.player,h.treasure)<1.65&&Math.abs(w.player.y-h.treasure.y)<.65){end(w,'won','treasure');}
}
export function settleHunt(w,save){const h=w.hunt;if(!h||h.status==='running'||h.paid)return null;h.paid=true;let reward=0,breakdown=null;if(h.status==='won'){breakdown=huntReward(w);reward=Object.values(breakdown).reduce((a,b)=>a+b,0);save.coins+=reward;save.huntWins=(save.huntWins||0)+1;save.huntBest=save.huntBest===null||!Number.isFinite(save.huntBest)?w.clock:Math.min(save.huntBest,w.clock);if(h.level>=(save.huntLevel||1)){save.huntLevel=h.level+1;save.huntLastRoof=h.treasure.roofId;}}h.reward=reward;return {won:h.status==='won',reason:h.reason,reward,breakdown,level:h.level,time:w.clock,lives:h.lives,treasure:h.treasure.name};}

import {clamp,cameraMove} from './math.mjs';
export class ParkourInput{
 constructor(canvas,orbit,isRunning,onPause){this.canvas=canvas;this.orbit=orbit;this.isRunning=isRunning;this.onPause=onPause;this.keys=new Set();this.stick={x:0,y:0};this.pending={jump:false,slide:false,trick:false};this.autoRun=false;this.fastRun=false;this.drag=null;this.knob=null;
  window.addEventListener('keydown',e=>{if(e.code==='Escape'){e.preventDefault();onPause();return;}if(!isRunning()||e.target?.matches('input,textarea,[contenteditable=true]'))return;
   if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyW','KeyA','KeyS','KeyD','ShiftLeft','ShiftRight','KeyC','KeyF','KeyR','KeyQ','KeyE'].includes(e.code))e.preventDefault();this.keys.add(e.code);if(e.repeat)return;
   if(e.code==='Space')this.pending.jump=true;if(e.code==='KeyC')this.pending.slide=true;if(e.code==='KeyF'||e.code==='KeyG'){this.pending.trick=true;this.pending.trickKind=e.code==='KeyG'?'side':'front';}if(e.code==='KeyB')this.pending.marker=true;if(e.code==='KeyX')this.pending.return=true;if(e.code==='KeyT')this.pending.tool=true;if(e.code==='KeyZ')this.slowmo=!this.slowmo;if(e.code==='KeyR')this.autoRun=!this.autoRun;if(e.code==='KeyQ')this.orbit.yaw+=.18;if(e.code==='KeyE')this.orbit.yaw-=.18;
  });window.addEventListener('keyup',e=>this.keys.delete(e.code));window.addEventListener('blur',()=>{this.reset();if(isRunning())onPause();});
  canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{if(!isRunning())return;this.drag={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});
  canvas.addEventListener('pointermove',e=>{if(!this.drag||e.pointerId!==this.drag.id)return;this.orbit.manual=2;this.orbit.yaw-=(e.clientX-this.drag.x)*.006;this.orbit.pitch=clamp(this.orbit.pitch+(e.clientY-this.drag.y)*.004,.03,.64);this.drag.x=e.clientX;this.drag.y=e.clientY;});
  const release=e=>{if(this.drag?.id===e.pointerId)this.drag=null;};canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
 }
 bindHUD(ui){const stick=ui.querySelector('#stick'),knob=ui.querySelector('#stick-knob');this.knob=knob;if(stick){let pointer=null;const update=e=>{const r=stick.getBoundingClientRect(),dx=e.clientX-r.x-r.width/2,dy=e.clientY-r.y-r.height/2,max=r.width*.31,n=Math.max(1,Math.hypot(dx,dy)/max);this.stick.x=clamp(dx/max/n,-1,1);this.stick.y=clamp(-dy/max/n,-1,1);knob.style.transform=`translate(${this.stick.x*max}px,${-this.stick.y*max}px)`;};stick.addEventListener('pointerdown',e=>{e.preventDefault();this.autoRun=false;pointer=e.pointerId;stick.setPointerCapture(pointer);update(e);});stick.addEventListener('pointermove',e=>{if(e.pointerId===pointer)update(e);});const release=e=>{if(e.pointerId!==pointer)return;pointer=null;this.stick.x=this.stick.y=0;knob.style.transform='translate(0,0)';};stick.addEventListener('pointerup',release);stick.addEventListener('pointercancel',release);}
  for(const action of['jump','slide','trick','sideflip']){const b=ui.querySelector(`[data-action="${action}"]`);if(!b)continue;const trigger=()=>{this.pending[action==='sideflip'?'trick':action]=true;if(action==='trick'||action==='sideflip')this.pending.trickKind=action==='sideflip'?'side':'front';};b.addEventListener('pointerdown',e=>{if(!this.isRunning())return;e.preventDefault();trigger();});b.addEventListener('click',e=>{if(e.detail===0&&this.isRunning())trigger();});}
 }
 read(dt){const k=this.keys,x=clamp((k.has('KeyD')||k.has('ArrowRight')?1:0)-(k.has('KeyA')||k.has('ArrowLeft')?1:0)+this.stick.x,-1,1),forward=clamp((k.has('KeyW')||k.has('ArrowUp')?1:0)-(k.has('KeyS')||k.has('ArrowDown')?1:0)+this.stick.y+(this.autoRun?1:0),-1,1);if(k.has('KeyQ'))this.orbit.yaw+=dt*1.25;if(k.has('KeyE'))this.orbit.yaw-=dt*1.25;const world=cameraMove(x,forward,this.orbit.yaw),out={...world,sprint:this.fastRun||k.has('ShiftLeft')||k.has('ShiftRight')||Math.hypot(this.stick.x,this.stick.y)>.9,...this.pending};this.pending={jump:false,slide:false,trick:false};return out;}
 reset(){this.keys.clear();this.stick.x=this.stick.y=0;this.pending={jump:false,slide:false,trick:false};this.autoRun=false;this.drag=null;if(this.knob)this.knob.style.transform='translate(0,0)';}
}

import * as T from '../vendor/three.module.js';
