   const x=ix*CELL,z=iz*CELL,near=this.buckets.get(ix+','+iz)||[],tops=[];
   for(const b of near)if(b.w>.85&&b.d>.85&&b.maxY>20&&!b.noTop&&insideXZ(b,x,z,-R)&&!tops.some(y=>Math.abs(y-b.maxY)<.08)){
